<script setup lang="ts">
import { computed } from 'vue'; import { Head,Link,useForm } from '@inertiajs/vue3'; import InventoryNav from '../../Components/Common/InventoryNav.vue';
interface Supplier{id:number;code:string;legal_name:string;payment_terms_days:number} interface Location{id:number;name:string;warehouse:string} interface Product{id:number;sku:string;name:string;average_cost:string;unit_id:number;unit:string} interface Treasury{id:number;name:string;type:string}
const props=defineProps<{suppliers:Supplier[];locations:Location[];products:Product[];treasuryAccounts:Treasury[]}>(); type Line={product_id:number|string;unit_id:number|string;quantity:number;unit_cost:number;discount:number;tax_rate:number};
const today=new Date().toISOString().slice(0,10); const form=useForm({operation_key:crypto.randomUUID(),supplier_id:'',location_id:'',supplier_document:'',document_date:today,due_date:'',payment_type:'credit',treasury_account_id:'',payment_method:'bank_transfer',paid_amount:0,notes:'',lines:[{product_id:'',unit_id:'',quantity:1,unit_cost:0,discount:0,tax_rate:15}] as Line[]});
const productChanged=(l:Line)=>{const p=props.products.find(x=>x.id===Number(l.product_id));if(p){l.unit_id=p.unit_id;l.unit_cost=Number(p.average_cost)}}; const supplierChanged=()=>{const s=props.suppliers.find(x=>x.id===Number(form.supplier_id));if(s&&s.payment_terms_days){const d=new Date(`${form.document_date}T12:00:00`);d.setDate(d.getDate()+s.payment_terms_days);form.due_date=d.toISOString().slice(0,10)}};
const totals=computed(()=>form.lines.reduce((a,l)=>{const gross=l.quantity*l.unit_cost,net=Math.max(0,gross-l.discount),tax=net*l.tax_rate/100;return{subtotal:a.subtotal+gross,discount:a.discount+l.discount,tax:a.tax+tax,total:a.total+net+tax}},{subtotal:0,discount:0,tax:0,total:0}));
const add=()=>form.lines.push({product_id:'',unit_id:'',quantity:1,unit_cost:0,discount:0,tax_rate:15});const remove=(i:number)=>{if(form.lines.length>1)form.lines.splice(i,1)};const sync=()=>{if(form.payment_type==='cash')form.paid_amount=Number(totals.value.total.toFixed(2));else form.paid_amount=0}; const submit=()=>{sync();form.post('/purchases')};
</script>
<template><Head title="Nueva compra"/><main class="page"><InventoryNav/><div class="heading"><div><p class="eyebrow">COMPRAS</p><h1>Registrar compra de materiales</h1><p>La confirmación aumenta inventario, actualiza el costo promedio y contabiliza la factura.</p></div><Link href="/purchases">Volver</Link></div><form @submit.prevent="submit"><section class="card grid"><label>Proveedor *<select v-model="form.supplier_id" required @change="supplierChanged"><option value="">Selecciona</option><option v-for="s in suppliers" :key="s.id" :value="s.id">{{s.code}} — {{s.legal_name}}</option></select></label><label>Ubicación de ingreso *<select v-model="form.location_id" required><option value="">Selecciona</option><option v-for="l in locations" :key="l.id" :value="l.id">{{l.warehouse}} / {{l.name}}</option></select></label><label>Factura del proveedor<input v-model="form.supplier_document" maxlength="100"></label><label>Fecha *<input v-model="form.document_date" type="date" required></label><label>Vencimiento<input v-model="form.due_date" type="date"></label><label>Condición<select v-model="form.payment_type" @change="sync"><option value="credit">Crédito</option><option value="cash">Contado</option></select></label><label v-if="form.payment_type==='cash'">Caja o banco *<select v-model="form.treasury_account_id" required><option value="">Selecciona</option><option v-for="a in treasuryAccounts" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label class="wide">Notas<textarea v-model="form.notes"/></label></section><section class="card"><h2>Materiales</h2><div v-for="(l,i) in form.lines" :key="i" class="line"><select v-model="l.product_id" required @change="productChanged(l)"><option value="">Producto</option><option v-for="p in products" :key="p.id" :value="p.id">{{p.sku}} — {{p.name}} ({{p.unit}})</option></select><input v-model.number="l.quantity" type="number" min=".0001" step=".0001" placeholder="Cantidad" required><input v-model.number="l.unit_cost" type="number" min="0" step=".0001" placeholder="Costo unitario" required><input v-model.number="l.discount" type="number" min="0" step=".01" placeholder="Descuento"><input v-model.number="l.tax_rate" type="number" min="0" max="100" step=".01" placeholder="ISV %"><button type="button" class="danger" @click="remove(i)">×</button></div><button type="button" class="secondary" @click="add">+ Agregar producto</button><div class="totals"><span>Subtotal: {{totals.subtotal.toFixed(2)}}</span><span>Descuento: {{totals.discount.toFixed(2)}}</span><span>Impuesto: {{totals.tax.toFixed(2)}}</span><strong>Total: {{totals.total.toFixed(2)}}</strong></div></section><p class="error">{{Object.values(form.errors)[0]}}</p><div class="actions"><Link href="/purchases">Cancelar</Link><button :disabled="form.processing">Confirmar compra</button></div></form></main></template>
<style scoped>.page{max-width:1500px;margin:auto;padding:2rem}.heading{display:flex;justify-content:space-between;align-items:center}.heading a{color:var(--p-primary-color)}.eyebrow{color:var(--p-primary-color);font-weight:800;font-size:.75rem;letter-spacing:.15em}.card{padding:1.5rem;border:1px solid var(--p-content-border-color);border-radius:1rem;margin:1rem 0;background:var(--p-content-background)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.wide{grid-column:1/-1}label{display:grid;gap:.4rem;font-weight:600}input,select,textarea{padding:.75rem;border:1px solid var(--p-content-border-color);border-radius:.5rem;background:transparent;color:inherit;min-width:0}textarea{min-height:5rem}.line{display:grid;grid-template-columns:2fr repeat(4,1fr) auto;gap:.6rem;margin-bottom:.7rem}.totals,.actions{display:flex;justify-content:flex-end;gap:1.5rem;flex-wrap:wrap;margin-top:1rem}.actions a,button{padding:.7rem 1rem;border:0;border-radius:.5rem;background:var(--p-primary-color);color:var(--p-primary-contrast-color);font-weight:700;text-decoration:none}.actions a,.secondary{background:transparent;color:inherit;border:1px solid var(--p-content-border-color)}.danger{background:#ef4444}.error{color:#ef4444}@media(max-width:900px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}.line{grid-template-columns:1fr 1fr}.line select{grid-column:1/-1}}</style>
